oxy_webhelp_navlinks = {"saphana_manage_data-d39307e41216":{"topics":[{"title":"Legal hold for snapshot retention","shortdesc":"<p class=\"shortdesc\">Legal hold ensures that snapshots are retained indefinitely until the hold is         removed, overriding the scheduled expiry of an SLA Domain policy. This ensures that         snapshots are available as long as necessary to meet legal obligations.<\/p>","href":"saas\/legal_hold_snapshot_rtn_2.html","attributes":{"data-id":"legal_hold_snapshot_rtn"},"menu":{"hasChildren":false},"tocID":"legal_hold_snapshot_rtn-d39307e41227","next":"legal_hold_snapshot_rtn-d39307e41227"},{"title":"Manage retention of SAP HANA snapshots","shortdesc":"<p class=\"shortdesc\">To meet data governance and regulatory compliance, you can increase the retention         period of individual SAP HANA snapshots, as required.<\/p>","href":"saas\/manage_retention_sap_hana_snapshots.html","attributes":{"data-id":"manage_retention_sap_hana_snapshots"},"menu":{"hasChildren":false},"tocID":"manage_retention_sap_hana_snapshots-d39307e41263","next":"manage_retention_sap_hana_snapshots-d39307e41263"},{"title":"SAP HANA database details","shortdesc":"<p class=\"shortdesc\">The details page for an SAP HANA database displays the protection status, snapshot         calendar, and protection events list.<\/p>","href":"saas\/sap_hana_database_details.html","attributes":{"data-id":"sap_hana_database_details"},"menu":{"hasChildren":false},"tocID":"sap_hana_database_details-d39307e41285","topics":[]}]}};